def mcq(question,options,answer,marks=1): return {'type':'mcq','marks':marks,'question':question,'options':options,'correctIdx':answer}
def ar(question,options,answer): return {'type':'ar','marks':1,'question':question,'options':options,'correctIdx':answer}
def sub(question,answer,marks=2): return {'type':'subjective','marks':marks,'question':question,'sampleAnswer':answer}
