def ncert_html():
    blocks=[]
    for qno,question,options,answer,marks in _engine.NCERT:
        oh=''
        if options:
            oh='<div class="sj-ncert-options"><ol>'+''.join(f'<li>{html.escape(str(o))}</li>' for o in options)+'</ol></div>'
        blocks.append(f'<div class="sj-ncert-question"><div class="sj-ncert-qtop"><div class="sj-ncert-qnumber">{qno}.</div><span class="marks-badge">{marks} Marks</span></div><div class="sj-ncert-qtext">{(question if qno == 15 else html.escape(question))}</div>{oh}<details class="sj-ncert-answer"><summary>View Solution &amp; Marking Scheme</summary><div class="sj-answer-content">{answer}</div></details></div>')
    journey='<section class="sj-card"><div class="sj-cheader"><div class="sj-cicon"><i class="fas fa-route"></i></div><div><h2>The Journey Beyond</h2></div></div><ul><li>Visit a nearby park or a water body. Observe the water body and its surroundings. Identify ten organisms and classify them into kingdoms.</li><li>Interview a gardener or a forest worker. Ask them how they identify species. Compare the traditional scientific methods of identification.</li><li>If you were studying the Pakke Tiger Reserve or any other bird sanctuary of your choice, how would you organise the information about the bird species?</li><li>Conduct a survey in a forest area near a village, identify edible and poisonous mushrooms with the help of indigenous knowledge of community resource person(s).</li><li>Collect and study the postal stamps of India and the world released over time on diversified flora and fauna. Based on your learning, make your own criteria and classify them. Organise a philately (collection of postage stamps) exhibition in your school and showcase your work in this exhibition.</li><li>Investigate an extinct species and analyse how its disappearance impacted the organisms that depend on it, and how this affected the ecological balance of the ecosystem.</li><li>Study the diversity of farm animals used in different types of farming practices in various parts of the country.</li></ul><p>What knowledge do you think scientists would come up with further and how would it affect the classification system?</p></section>'
    quest='<section class="sj-card"><div class="sj-cheader"><div class="sj-cicon"><i class="fas fa-compass"></i></div><div><h2>The Quest Continues…</h2></div></div><div class="sj-exercise-q"><p><strong>(vi)</strong> If classification were based only on habitat, which organisms might be incorrectly grouped together? Explain the scientific consequences of such a classification.</p><details class="sj-ncert-answer"><summary>View Solution</summary><div class="sj-answer-content"><p>Organisms sharing a habitat could be unrelated and could differ in cellular organisation, nutrition, body structure and ancestry. Such a system would group organisms that do not share meaningful biological relationships and could obscure evolutionary relationships.</p></div></details></div><div class="sj-exercise-q"><p><strong>(vii)</strong> Imagine scientists discover a new organism that is multicellular, eukaryotic, lacks chlorophyll and absorbs nutrients from a host externally. Should it be placed under fungi or animalia? Justify your reasoning using classification criteria.</p><details class="sj-ncert-answer"><summary>View Solution</summary><div class="sj-answer-content"><p><strong>Fungi</strong> would be the closer placement using the chapter\'s criteria. The organism is multicellular and eukaryotic, lacks chlorophyll and obtains nutrition by absorption, which aligns with fungal characteristics.</p></div></details></div></section>'
    return f'<section class="sj-card"><div class="sj-cheader"><div class="sj-cicon"><i class="fas fa-pencil-ruler"></i></div><div><h2>Revise, Reflect, Refine</h2></div></div>{"".join(blocks)}</section>{journey}{quest}'
_engine.ncert_html=ncert_html

def build_content_page(page_type,content):
    doc=_engine.TEMPLATES[page_type].read_text(encoding='utf-8')
    doc=_engine.update_metadata(doc,page_type); doc=_engine.replace_tbar(doc,page_type); doc=_engine.replace_page_content(doc,content,page_type); doc=inject_css(doc)
    doc=doc.replace('<body>',f'<body>\n<!-- SJMaths Class 9 Science | Chapter 12 | Page: {page_type} -->',1)
    out=CH12/page_type; out.mkdir(parents=True,exist_ok=True); (out/'index.html').write_text(doc,encoding='utf-8'); print('✓',out/'index.html')
_engine.build_content_page=build_content_page
_engine.DESCRIPTIONS={'concepts':'Detailed Class 9 Science Chapter 12 concepts: biodiversity, classification criteria, five kingdoms, plant groups, animal phyla, vertebrates, hierarchy, binomial nomenclature, three domains, fossils and conservation.','ncert-exercises':'Chapter 12 Revise, Reflect, Refine questions, The Journey Beyond activities and The Quest Continues prompts.','quiz':'30-question interactive Chapter 12 quiz covering biodiversity, classification, five kingdoms, plants, animals, hierarchy and nomenclature.','tests':'Chapter 12 Basic, Standard and Advanced tests with MCQ, Assertion-Reason, subjective and case-based questions.','revision-notes':'Master Chapter 12 revision: complete comparisons, mnemonics, hierarchy, classification timeline, exam traps and rapid recall.'}

def main():
    original_print=builtins.print
    def p(*args,**kwargs):
        vals=[]
        for v in args:
            if isinstance(v,str):
                for old,new in {'Chapter 9':'Chapter 12','Atomic Foundations of Matter':'Patterns in Life: Diversity and Classification','CONTENT:     Chapter 9':'CONTENT:     Chapter 12','chapter-9-atomic-foundations-of-matter/':CH12_FOLDER+'/' ,'✓ CHAPTER 9 COMPLETE':'✓ CHAPTER 12 COMPLETE'}.items(): v=v.replace(old,new)
            vals.append(v)
        original_print(*vals,**kwargs)
    builtins.print=p
    try: _engine.main()
    finally: builtins.print=original_print
if __name__=='__main__': main()